class Motor(val name: String, val speed: Double) {
    override fun toString(): String {
        return "Motor(name=$name, speed=$speed)"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testToString() {
        val motor = Motor("Left Drive", 0.75)
        Assert.assertEquals("Motor(name=Left Drive, speed=0.75)", motor.toString())
    }

    @Test
    fun testToStringZeroSpeed() {
        val motor = Motor("Intake", 0.0)
        Assert.assertEquals("Motor(name=Intake, speed=0.0)", motor.toString())
    }

    @Test
    fun testPrintUsesToString() {
        val motor = Motor("Shooter", 1.0)
        Assert.assertTrue(motor.toString().contains("Shooter"))
        Assert.assertTrue(motor.toString().contains("1.0"))
    }
}
